/* @autogenerated */
package net.civeira.phylax.features.oauth.delegatelogin.domain.gateway;

import java.util.Optional;

/**
 * Port for the accounts that each external identity may enter.
 *
 * Responsibilities: - Find the account linked to a provider subject. - Record new links once.
 *
 * Design notes: - A link is per login provider record (its uid), not per provider type, so two
 * providers of the same tenant never share links. - Backed by the Access entity
 * {@code user-federated-identity}, unique by (login-provider, subject).
 */
public interface FederatedIdentityGateway {
  /**
   * Returns the user linked to a subject of a provider.
   *
   * @param providerUid uid of the tenant login provider
   * @param subject provider subject
   * @return uid of the linked user
   */
  Optional<String> linkedUser(String providerUid, String subject);

  /**
   * Links a subject of a provider to a user, unless it is already linked.
   *
   * When a concurrent access linked the subject first, returns the user of that link.
   *
   * @param providerUid uid of the tenant login provider
   * @param subject provider subject
   * @param userUid uid of the user to link
   * @return uid of the user linked to the subject after the call
   */
  String link(String providerUid, String subject, String userUid);

  /**
   * Checks whether a user is linked to a provider with any subject.
   *
   * @param userUid uid of the user
   * @param providerUid uid of the tenant login provider
   * @return true when a link exists
   */
  boolean isLinkedTo(String userUid, String providerUid);

  /**
   * Checks whether a user has any federated link.
   *
   * @param userUid uid of the user
   * @return true when a link exists
   */
  boolean hasLinks(String userUid);
}
